import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// Adds the licences of the native Android libraries (AndroidX, CameraX,
/// ML Kit...) to Flutter's licence page, which only collects Dart packages
/// and the engine. The file is generated by tool/native_licenses.py.
void registerNativeLicenses() {
  if (defaultTargetPlatform != TargetPlatform.android) return;
  LicenseRegistry.addLicense(() async* {
    final text = await rootBundle.loadString('assets/licenses/android.txt');
    // Each entry: a line of comma-separated libraries, then the licence.
    for (final entry in text.split('\n--------\n')) {
      final newline = entry.indexOf('\n');
      if (newline < 0) continue;
      yield LicenseEntryWithLineBreaks(
        entry.substring(0, newline).split(', '),
        entry.substring(newline + 1),
      );
    }
  });
}
